-- VidhiVerse AI -- SQLite schema (minimal architecture: no Docker, no server process).
--
-- The database is a single file (e.g. storage/vidhiverse.db) opened directly by the
-- backend. Apply this file with database/schema/apply_schema.py, which loads the
-- sqlite-vec extension and turns on foreign-key enforcement before running it.
--
-- Mapping from the original PostgreSQL design (docs/technical/11-database-schema.md):
--   uuid PK                  -> TEXT PK; value generated by the app (str(uuid.uuid4()))
--   timestamptz              -> TEXT, ISO-8601 UTC, e.g. 2026-11-17T09:30:00.000Z
--   date                     -> TEXT, ISO-8601 date, e.g. 2026-11-17 (sorts correctly as text)
--   jsonb                    -> TEXT + CHECK(json_valid(...)) (JSON1, built into SQLite)
--   citext                   -> TEXT COLLATE NOCASE
--   boolean                  -> INTEGER (0/1)
--   vector(n) + HNSW index   -> a sibling "<table>_vec" vec0 virtual table (sqlite-vec),
--                               row-keyed by the same TEXT id, written by the app once an
--                               embedding is computed. No join is needed for a kNN query:
--                               "SELECT id, distance FROM x_vec WHERE embedding MATCH ? AND k = ?"
--   tsvector + GIN           -> a sibling "<table>_fts" FTS5 external-content table, kept in
--                               sync by AFTER INSERT/UPDATE/DELETE triggers on the base table
--   pg_trgm GIN              -> an FTS5 virtual table with tokenize='trigram'
--
-- PRAGMA foreign_keys is a per-connection setting in SQLite and is NOT stored in the
-- database file -- the app must issue "PRAGMA foreign_keys = ON;" on every new connection
-- (apply_schema.py does this, and so should the backend's engine/session setup).

PRAGMA foreign_keys = ON;

-- ============================================================================
-- Identity, sessions, chat
-- ============================================================================

CREATE TABLE users (
  id TEXT PRIMARY KEY,
  email TEXT COLLATE NOCASE UNIQUE,
  password_hash TEXT,
  display_name TEXT,
  role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin')),
  is_guest INTEGER NOT NULL DEFAULT 0,
  guest_expires_at TEXT,
  privacy_notice_version TEXT,
  privacy_notice_accepted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at TEXT,
  CHECK (is_guest OR (email IS NOT NULL AND password_hash IS NOT NULL)),
  CHECK (NOT is_guest OR guest_expires_at IS NOT NULL)
);
CREATE INDEX idx_users_guest_expiry ON users (guest_expires_at) WHERE is_guest;

CREATE TABLE user_preferences (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  preferred_language TEXT NOT NULL DEFAULT 'en',
  state_code TEXT,
  store_history INTEGER NOT NULL DEFAULT 1,
  document_retention_days INTEGER NOT NULL DEFAULT 30 CHECK (document_retention_days BETWEEN 1 AND 365),
  voice_output_enabled INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE refresh_tokens (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  family_id TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  revoked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_refresh_user ON refresh_tokens (user_id);
CREATE INDEX idx_refresh_family ON refresh_tokens (family_id);

CREATE TABLE chat_sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT,
  language TEXT NOT NULL DEFAULT 'en',
  state_code TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_message_at TEXT,
  deleted_at TEXT
);
CREATE INDEX idx_sessions_user_recent ON chat_sessions (user_id, last_message_at DESC) WHERE deleted_at IS NULL;

CREATE TABLE chat_messages (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES chat_sessions(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('user','assistant')),
  language TEXT NOT NULL,
  content TEXT NOT NULL,
  content_en TEXT,
  answer_status TEXT CHECK (answer_status IN ('answered','needs_clarification','insufficient_sources','refused','urgent_referral')),
  structured_answer TEXT CHECK (structured_answer IS NULL OR json_valid(structured_answer)),
  intent TEXT,
  urgency TEXT CHECK (urgency IN ('none','elevated','immediate_safety')),
  event_date TEXT,
  law_as_of TEXT,
  translation_status TEXT CHECK (translation_status IN ('not_needed','ok','failed')),
  retrieval_trace TEXT CHECK (retrieval_trace IS NULL OR json_valid(retrieval_trace)),
  prompt_version TEXT,
  llm_provider TEXT,
  llm_model TEXT,
  input_tokens INTEGER,
  output_tokens INTEGER,
  latency_ms INTEGER,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK ((role = 'assistant') = (answer_status IS NOT NULL))
);
CREATE INDEX idx_messages_session ON chat_messages (session_id, created_at);
CREATE INDEX idx_messages_user ON chat_messages (user_id);

-- ============================================================================
-- Legal corpus
-- ============================================================================

CREATE TABLE legal_sources (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  publisher TEXT NOT NULL,
  source_type TEXT NOT NULL CHECK (source_type IN ('constitution','central_act','state_act','rules','regulations','notification','judgment','government_resource')),
  jurisdiction_level TEXT NOT NULL CHECK (jurisdiction_level IN ('national','central','state','union_territory')),
  state_code TEXT,
  source_url TEXT NOT NULL,
  storage_key TEXT,
  checksum_sha256 TEXT,
  original_language TEXT NOT NULL DEFAULT 'en',
  version_label TEXT,
  licence_note TEXT,
  retrieved_at TEXT,
  last_verified_at TEXT,
  verified_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (source_url, checksum_sha256)
);
CREATE INDEX idx_sources_status ON legal_sources (validation_status, source_type);

CREATE TABLE legal_acts (
  id TEXT PRIMARY KEY,
  act_key TEXT NOT NULL UNIQUE,
  short_title TEXT NOT NULL,
  full_title TEXT,
  act_number TEXT,
  year INTEGER,
  source_type TEXT NOT NULL CHECK (source_type IN ('constitution','central_act','state_act','rules','regulations','notification')),
  jurisdiction_level TEXT NOT NULL CHECK (jurisdiction_level IN ('national','central','state','union_territory')),
  state_code TEXT,
  enactment_date TEXT,
  commencement_date TEXT,
  commencement_note TEXT,
  effective_status TEXT NOT NULL DEFAULT 'unknown' CHECK (effective_status IN ('in_force','partially_in_force','not_yet_in_force','repealed','superseded_version','unknown')),
  repealed_by_act_id TEXT REFERENCES legal_acts(id),
  repealed_on TEXT,
  amendment_history TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(amendment_history)),
  original_language TEXT NOT NULL DEFAULT 'en',
  source_id TEXT NOT NULL REFERENCES legal_sources(id),
  last_verified_at TEXT,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_acts_jurisdiction ON legal_acts (jurisdiction_level, state_code);

-- Fuzzy title search (replaces pg_trgm GIN index idx_acts_title_trgm).
CREATE VIRTUAL TABLE legal_acts_title_trgm USING fts5(short_title, content='legal_acts', content_rowid='rowid', tokenize='trigram');
CREATE TRIGGER legal_acts_title_trgm_ai AFTER INSERT ON legal_acts BEGIN
  INSERT INTO legal_acts_title_trgm(rowid, short_title) VALUES (new.rowid, new.short_title);
END;
CREATE TRIGGER legal_acts_title_trgm_ad AFTER DELETE ON legal_acts BEGIN
  INSERT INTO legal_acts_title_trgm(legal_acts_title_trgm, rowid, short_title) VALUES ('delete', old.rowid, old.short_title);
END;
CREATE TRIGGER legal_acts_title_trgm_au AFTER UPDATE ON legal_acts BEGIN
  INSERT INTO legal_acts_title_trgm(legal_acts_title_trgm, rowid, short_title) VALUES ('delete', old.rowid, old.short_title);
  INSERT INTO legal_acts_title_trgm(rowid, short_title) VALUES (new.rowid, new.short_title);
END;

CREATE TABLE legal_sections (
  id TEXT PRIMARY KEY,
  act_id TEXT NOT NULL REFERENCES legal_acts(id),
  part_label TEXT,
  chapter_label TEXT,
  chapter_title TEXT,
  section_number TEXT NOT NULL,
  sort_key INTEGER NOT NULL,
  heading TEXT,
  text_original TEXT NOT NULL,
  language TEXT NOT NULL DEFAULT 'en',
  version_no INTEGER NOT NULL DEFAULT 1,
  valid_from TEXT NOT NULL,
  valid_to TEXT,
  effective_status TEXT NOT NULL DEFAULT 'unknown' CHECK (effective_status IN ('in_force','partially_in_force','not_yet_in_force','repealed','superseded_version','unknown')),
  amendment_note TEXT,
  source_id TEXT NOT NULL REFERENCES legal_sources(id),
  page_start INTEGER,
  page_end INTEGER,
  last_verified_at TEXT,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (act_id, section_number, version_no, language),
  CHECK (valid_to IS NULL OR valid_to >= valid_from)
);
CREATE INDEX idx_sections_lookup ON legal_sections (act_id, section_number, valid_from);

CREATE TABLE legal_cases (
  id TEXT PRIMARY KEY,
  case_title TEXT NOT NULL,
  neutral_citation TEXT,
  reporter_citation TEXT,
  court TEXT NOT NULL,
  jurisdiction_level TEXT NOT NULL DEFAULT 'national',
  state_code TEXT,
  bench TEXT,
  decision_date TEXT NOT NULL,
  verified_summary TEXT,
  source_id TEXT NOT NULL REFERENCES legal_sources(id),
  last_verified_at TEXT,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_cases_date ON legal_cases (court, decision_date DESC);
CREATE UNIQUE INDEX uq_cases_neutral ON legal_cases (neutral_citation) WHERE neutral_citation IS NOT NULL;

-- Fuzzy title search (replaces pg_trgm GIN index idx_cases_title_trgm).
CREATE VIRTUAL TABLE legal_cases_title_trgm USING fts5(case_title, content='legal_cases', content_rowid='rowid', tokenize='trigram');
CREATE TRIGGER legal_cases_title_trgm_ai AFTER INSERT ON legal_cases BEGIN
  INSERT INTO legal_cases_title_trgm(rowid, case_title) VALUES (new.rowid, new.case_title);
END;
CREATE TRIGGER legal_cases_title_trgm_ad AFTER DELETE ON legal_cases BEGIN
  INSERT INTO legal_cases_title_trgm(legal_cases_title_trgm, rowid, case_title) VALUES ('delete', old.rowid, old.case_title);
END;
CREATE TRIGGER legal_cases_title_trgm_au AFTER UPDATE ON legal_cases BEGIN
  INSERT INTO legal_cases_title_trgm(legal_cases_title_trgm, rowid, case_title) VALUES ('delete', old.rowid, old.case_title);
  INSERT INTO legal_cases_title_trgm(rowid, case_title) VALUES (new.rowid, new.case_title);
END;

CREATE TABLE legal_chunks (
  id TEXT PRIMARY KEY,
  section_id TEXT REFERENCES legal_sections(id),
  case_id TEXT REFERENCES legal_cases(id),
  source_id TEXT NOT NULL REFERENCES legal_sources(id),
  chunk_index INTEGER NOT NULL,
  subsection_ref TEXT,
  content TEXT NOT NULL,
  content_language TEXT NOT NULL DEFAULT 'en',
  token_count INTEGER,
  jurisdiction_level TEXT NOT NULL CHECK (jurisdiction_level IN ('national','central','state','union_territory')),
  state_code TEXT,
  valid_from TEXT NOT NULL,
  valid_to TEXT,
  effective_status TEXT NOT NULL CHECK (effective_status IN ('in_force','partially_in_force','not_yet_in_force','repealed','superseded_version','unknown')),
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  embedding_model TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK ((section_id IS NOT NULL) <> (case_id IS NOT NULL))
);
CREATE INDEX idx_chunks_filter ON legal_chunks (validation_status, jurisdiction_level, state_code, valid_from, valid_to);
CREATE UNIQUE INDEX uq_chunks_section ON legal_chunks (section_id, chunk_index) WHERE section_id IS NOT NULL;
CREATE UNIQUE INDEX uq_chunks_case ON legal_chunks (case_id, chunk_index) WHERE case_id IS NOT NULL;

-- Semantic search (replaces "embedding vector(384)" + HNSW index idx_chunks_embedding).
-- Written by the app once a chunk's embedding is computed; query with:
--   SELECT id, distance FROM legal_chunks_vec WHERE embedding MATCH :query AND k = :k ORDER BY distance;
CREATE VIRTUAL TABLE legal_chunks_vec USING vec0(id TEXT PRIMARY KEY, embedding float[384]);

-- Keyword search, English stemming (replaces "tsv tsvector ... to_tsvector('english', ...)" + GIN idx_chunks_tsv).
CREATE VIRTUAL TABLE legal_chunks_fts USING fts5(content, content='legal_chunks', content_rowid='rowid', tokenize='porter unicode61');
CREATE TRIGGER legal_chunks_fts_ai AFTER INSERT ON legal_chunks BEGIN
  INSERT INTO legal_chunks_fts(rowid, content) VALUES (new.rowid, new.content);
END;
CREATE TRIGGER legal_chunks_fts_ad AFTER DELETE ON legal_chunks BEGIN
  INSERT INTO legal_chunks_fts(legal_chunks_fts, rowid, content) VALUES ('delete', old.rowid, old.content);
END;
CREATE TRIGGER legal_chunks_fts_au AFTER UPDATE ON legal_chunks BEGIN
  INSERT INTO legal_chunks_fts(legal_chunks_fts, rowid, content) VALUES ('delete', old.rowid, old.content);
  INSERT INTO legal_chunks_fts(rowid, content) VALUES (new.rowid, new.content);
END;

CREATE TABLE legal_citations (
  id TEXT PRIMARY KEY,
  message_id TEXT NOT NULL REFERENCES chat_messages(id) ON DELETE CASCADE,
  marker TEXT NOT NULL,
  chunk_id TEXT NOT NULL REFERENCES legal_chunks(id),
  section_id TEXT REFERENCES legal_sections(id),
  case_id TEXT REFERENCES legal_cases(id),
  source_id TEXT NOT NULL REFERENCES legal_sources(id),
  is_related_only INTEGER NOT NULL DEFAULT 0,
  verification_status TEXT NOT NULL DEFAULT 'verified',
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (message_id, marker)
);
CREATE INDEX idx_citations_chunk ON legal_citations (chunk_id);

CREATE TABLE section_concordance (
  id TEXT PRIMARY KEY,
  old_section_id TEXT NOT NULL REFERENCES legal_sections(id),
  new_section_id TEXT REFERENCES legal_sections(id),
  relation TEXT NOT NULL CHECK (relation IN ('equivalent','partial','split','merged','omitted')),
  note TEXT,
  source_id TEXT REFERENCES legal_sources(id),
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (old_section_id, new_section_id)
);

-- ============================================================================
-- User documents
-- ============================================================================

CREATE TABLE user_documents (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  original_filename TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  page_count INTEGER,
  storage_key TEXT NOT NULL,
  checksum_sha256 TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'uploaded' CHECK (status IN ('uploaded','extracting','ocr','chunking','embedding','ready','failed','deleted')),
  ocr_used INTEGER NOT NULL DEFAULT 0,
  sensitive_data_flags TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(sensitive_data_flags)),
  summary_json TEXT CHECK (summary_json IS NULL OR json_valid(summary_json)),
  failure_reason TEXT,
  consent_at TEXT NOT NULL,
  retention_until TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at TEXT
);
CREATE INDEX idx_documents_user ON user_documents (user_id, created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX idx_documents_retention ON user_documents (retention_until) WHERE deleted_at IS NULL;

CREATE TABLE document_chunks (
  id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL REFERENCES user_documents(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  chunk_index INTEGER NOT NULL,
  page_number INTEGER,
  clause_ref TEXT,
  content TEXT NOT NULL,
  embedding_model TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (document_id, chunk_index)
);
CREATE INDEX idx_doc_chunks_doc ON document_chunks (document_id);

-- A user document's own chunks are few: brute-force vec0 search (no ANN index needed)
-- and a plain (unstemmed) FTS5 table are both exact and cheap at this size.
CREATE VIRTUAL TABLE document_chunks_vec USING vec0(id TEXT PRIMARY KEY, embedding float[384]);
CREATE VIRTUAL TABLE document_chunks_fts USING fts5(content, content='document_chunks', content_rowid='rowid', tokenize='unicode61');
CREATE TRIGGER document_chunks_fts_ai AFTER INSERT ON document_chunks BEGIN
  INSERT INTO document_chunks_fts(rowid, content) VALUES (new.rowid, new.content);
END;
CREATE TRIGGER document_chunks_fts_ad AFTER DELETE ON document_chunks BEGIN
  INSERT INTO document_chunks_fts(document_chunks_fts, rowid, content) VALUES ('delete', old.rowid, old.content);
END;
CREATE TRIGGER document_chunks_fts_au AFTER UPDATE ON document_chunks BEGIN
  INSERT INTO document_chunks_fts(document_chunks_fts, rowid, content) VALUES ('delete', old.rowid, old.content);
  INSERT INTO document_chunks_fts(rowid, content) VALUES (new.rowid, new.content);
END;

-- ============================================================================
-- Feedback, source discovery, ingestion
-- ============================================================================

CREATE TABLE feedback (
  id TEXT PRIMARY KEY,
  user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  message_id TEXT REFERENCES chat_messages(id) ON DELETE SET NULL,
  rating TEXT CHECK (rating IN ('up','down')),
  category TEXT NOT NULL DEFAULT 'general' CHECK (category IN ('general','wrong_law','wrong_citation','hard_to_understand','translation','bug','other')),
  comment TEXT,
  review_status TEXT NOT NULL DEFAULT 'new' CHECK (review_status IN ('new','reviewed','actioned')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX uq_feedback_user_message ON feedback (user_id, message_id) WHERE message_id IS NOT NULL;
CREATE INDEX idx_feedback_queue ON feedback (review_status, created_at);

CREATE TABLE source_updates (
  id TEXT PRIMARY KEY,
  source_id TEXT REFERENCES legal_sources(id),
  discovered_url TEXT NOT NULL UNIQUE,
  title TEXT,
  snippet TEXT,
  engine TEXT NOT NULL,
  bucket TEXT NOT NULL,
  is_official_domain INTEGER NOT NULL,
  classification TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','ingested')),
  reviewed_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  reviewed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_updates_queue ON source_updates (status, created_at);

CREATE TABLE ingestion_jobs (
  id TEXT PRIMARY KEY,
  job_type TEXT NOT NULL CHECK (job_type IN ('legal_parse','legal_publish','legal_reembed','document_process','document_analyze','retention_purge')),
  status TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','succeeded','failed','cancelled')),
  source_id TEXT REFERENCES legal_sources(id),
  document_id TEXT REFERENCES user_documents(id) ON DELETE CASCADE,
  payload TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(payload)),
  progress TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(progress)),
  attempts INTEGER NOT NULL DEFAULT 0,
  error TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  started_at TEXT,
  finished_at TEXT
);
CREATE INDEX idx_jobs_queue ON ingestion_jobs (status, created_at);

-- ============================================================================
-- Legal aid directory
-- ============================================================================

CREATE TABLE legal_aid_authorities (
  id TEXT PRIMARY KEY,
  authority_type TEXT NOT NULL CHECK (authority_type IN ('NALSA','SLSA','DLSA','TLSC','HCLSC','SCLSC')),
  name TEXT NOT NULL,
  state_code TEXT,
  district TEXT,
  address TEXT,
  phone TEXT,
  email TEXT,
  website_url TEXT,
  source_url TEXT NOT NULL,
  last_verified_at TEXT,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_authorities_location ON legal_aid_authorities (state_code, district);

CREATE TABLE legal_aid_resources (
  id TEXT PRIMARY KEY,
  authority_id TEXT REFERENCES legal_aid_authorities(id) ON DELETE SET NULL,
  resource_type TEXT NOT NULL CHECK (resource_type IN ('helpline','eligibility','application_link','scheme','information','government_service')),
  title TEXT NOT NULL,
  description TEXT,
  phone TEXT,
  url TEXT,
  state_code TEXT,
  language TEXT NOT NULL DEFAULT 'en',
  safety_topic TEXT,
  structured_data TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(structured_data)),
  source_url TEXT NOT NULL,
  last_verified_at TEXT,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_resources_type ON legal_aid_resources (resource_type, state_code, validation_status);

-- ============================================================================
-- Audit and SerpApi usage
-- ============================================================================

CREATE TABLE audit_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  action TEXT NOT NULL,
  entity_type TEXT,
  entity_id TEXT,
  request_id TEXT,
  metadata TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(metadata)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_audit_entity ON audit_logs (entity_type, entity_id);
CREATE INDEX idx_audit_time ON audit_logs (created_at);

CREATE TABLE serpapi_cache (
  query_hash TEXT PRIMARY KEY,
  engine TEXT NOT NULL,
  params TEXT NOT NULL CHECK (json_valid(params)),
  response_json TEXT NOT NULL CHECK (json_valid(response_json)),
  fetched_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  expires_at TEXT NOT NULL
);
CREATE INDEX idx_serp_cache_expiry ON serpapi_cache (expires_at);

CREATE TABLE serpapi_usage_logs (
  id TEXT PRIMARY KEY,
  event_type TEXT NOT NULL CHECK (event_type IN ('search','account_snapshot')),
  actor_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  bucket TEXT CHECK (bucket IN ('legal_discovery','case_discovery','updates','regional_resources','evaluation','reserve')),
  engine TEXT,
  query_text TEXT,
  query_hash TEXT REFERENCES serpapi_cache(query_hash) ON DELETE SET NULL,
  cache_hit INTEGER,
  estimated_credits INTEGER NOT NULL DEFAULT 0,
  status TEXT,
  result_count INTEGER,
  error TEXT,
  account_searches_left INTEGER,
  account_this_month_usage INTEGER,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_serp_usage ON serpapi_usage_logs (bucket, created_at);

-- ============================================================================
-- Document analysis (clauses, findings)
-- ============================================================================

CREATE TABLE document_clauses (
  id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL REFERENCES user_documents(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  clause_index INTEGER NOT NULL,
  clause_label TEXT,
  title TEXT,
  original_text TEXT NOT NULL,
  page_start INTEGER NOT NULL,
  page_end INTEGER NOT NULL,
  char_start INTEGER NOT NULL,
  char_end INTEGER NOT NULL,
  explanations TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(explanations)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (document_id, clause_index)
);
CREATE INDEX idx_clauses_user ON document_clauses (user_id);

CREATE TABLE document_findings (
  id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL REFERENCES user_documents(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  clause_id TEXT REFERENCES document_clauses(id) ON DELETE SET NULL,
  finding_type TEXT NOT NULL CHECK (finding_type IN ('obligation','deadline','penalty','important_term','possible_concern')),
  title TEXT NOT NULL,
  explanations TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(explanations)),
  party TEXT,
  due_date TEXT,
  due_text TEXT,
  amount_text TEXT,
  quote TEXT NOT NULL,
  page_number INTEGER NOT NULL,
  char_start INTEGER NOT NULL,
  char_end INTEGER NOT NULL,
  from_ocr INTEGER NOT NULL DEFAULT 0,
  confidence TEXT NOT NULL DEFAULT 'stated' CHECK (confidence IN ('stated','inferred_needs_review')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_findings_doc ON document_findings (document_id, finding_type);
CREATE INDEX idx_findings_user ON document_findings (user_id);

-- ============================================================================
-- Amendments and case-law links
-- ============================================================================

CREATE TABLE legal_amendments (
  id TEXT PRIMARY KEY,
  act_id TEXT NOT NULL REFERENCES legal_acts(id),
  section_id TEXT REFERENCES legal_sections(id),
  amending_title TEXT NOT NULL,
  effect TEXT NOT NULL CHECK (effect IN ('inserted','substituted','omitted','amended','repealed','other')),
  effective_date TEXT,
  notification_ref TEXT,
  note TEXT,
  source_id TEXT NOT NULL REFERENCES legal_sources(id),
  last_verified_at TEXT,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_amendments_act ON legal_amendments (act_id, effective_date DESC);
CREATE INDEX idx_amendments_section ON legal_amendments (section_id);

CREATE TABLE provision_case_links (
  id TEXT PRIMARY KEY,
  section_id TEXT NOT NULL REFERENCES legal_sections(id),
  case_id TEXT NOT NULL REFERENCES legal_cases(id),
  relation TEXT NOT NULL CHECK (relation IN ('interprets','applies','upholds','strikes_down','mentions')),
  paragraph_ref TEXT,
  note TEXT,
  link_origin TEXT NOT NULL DEFAULT 'curated' CHECK (link_origin IN ('curated','citation_extracted')),
  reviewed_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  last_verified_at TEXT,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (section_id, case_id, relation)
);
CREATE INDEX idx_links_case ON provision_case_links (case_id);

-- ============================================================================
-- Matters (personal case tracker)
-- ============================================================================

CREATE TABLE legal_matters (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  category TEXT,
  state_code TEXT,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  deleted_at TEXT
);
CREATE INDEX idx_matters_user ON legal_matters (user_id, updated_at DESC) WHERE deleted_at IS NULL;

CREATE TABLE matter_documents (
  matter_id TEXT NOT NULL REFERENCES legal_matters(id) ON DELETE CASCADE,
  document_id TEXT NOT NULL REFERENCES user_documents(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  added_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (matter_id, document_id)
);
CREATE INDEX idx_matter_docs_user ON matter_documents (user_id);

CREATE TABLE matter_events (
  id TEXT PRIMARY KEY,
  matter_id TEXT NOT NULL REFERENCES legal_matters(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  event_date TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  event_origin TEXT NOT NULL DEFAULT 'user' CHECK (event_origin IN ('user','document','workflow')),
  source_finding_id TEXT REFERENCES document_findings(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_events_matter ON matter_events (matter_id, event_date);

CREATE TABLE matter_deadlines (
  id TEXT PRIMARY KEY,
  matter_id TEXT NOT NULL REFERENCES legal_matters(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  due_date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','done','dismissed')),
  source_finding_id TEXT REFERENCES document_findings(id) ON DELETE SET NULL,
  confirmed_at TEXT NOT NULL,
  remind_at TEXT,
  reminder_seen_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_deadlines_due ON matter_deadlines (user_id, remind_at) WHERE status = 'pending';

CREATE TABLE matter_notes (
  id TEXT PRIMARY KEY,
  matter_id TEXT NOT NULL REFERENCES legal_matters(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  content TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_notes_matter ON matter_notes (matter_id, created_at DESC);

-- ============================================================================
-- Guided workflows
-- ============================================================================

CREATE TABLE workflow_templates (
  id TEXT PRIMARY KEY,
  template_key TEXT NOT NULL,
  version INTEGER NOT NULL,
  title_key TEXT NOT NULL,
  topic TEXT NOT NULL,
  jurisdiction_level TEXT NOT NULL CHECK (jurisdiction_level IN ('national','central','state','union_territory')),
  state_code TEXT,
  description TEXT NOT NULL,
  definition TEXT NOT NULL CHECK (json_valid(definition)),
  source_refs TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(source_refs)),
  reviewed_by TEXT,
  reviewed_at TEXT,
  last_verified_at TEXT,
  validation_status TEXT NOT NULL DEFAULT 'unverified' CHECK (validation_status IN ('unverified','verified','needs_review','rejected')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (template_key, version),
  CHECK (validation_status <> 'verified' OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL))
);
CREATE INDEX idx_templates_status ON workflow_templates (validation_status, topic);

-- Semantic search over template descriptions (replaces "description_embedding vector(384)").
CREATE VIRTUAL TABLE workflow_templates_vec USING vec0(id TEXT PRIMARY KEY, embedding float[384]);

CREATE TABLE workflow_runs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  template_id TEXT NOT NULL REFERENCES workflow_templates(id),
  matter_id TEXT REFERENCES legal_matters(id) ON DELETE SET NULL,
  language TEXT NOT NULL DEFAULT 'en',
  state_code TEXT,
  answers TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(answers)),
  status TEXT NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress','completed','abandoned')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_runs_user ON workflow_runs (user_id, updated_at DESC);

CREATE TABLE workflow_checklist_items (
  id TEXT PRIMARY KEY,
  run_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  item_key TEXT NOT NULL,
  item_type TEXT NOT NULL CHECK (item_type IN ('document','step','authority')),
  sort_order INTEGER NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','done','not_applicable')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (run_id, item_key)
);
CREATE INDEX idx_items_user ON workflow_checklist_items (user_id);
